def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]
    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_d = opp.count('D')
    opp_c = n - opp_d

    win = 10 if n >= 10 else n
    r_opp = opp[-win:]
    r_my = me[-win:]
    r_opp_d = r_opp.count('D')
    r_my_d = r_my.count('D')

    d_to_c = 0
    d_to_d = 0
    c_to_c = 0
    c_to_d = 0
    opp_changes = 0

    for i in range(1, n):
        if opp[i] != opp[i - 1]:
            opp_changes += 1

        a = me[i - 1]
        b = opp[i]

        if a == 'D':
            if b == 'C':
                d_to_c += 1
            else:
                d_to_d += 1
        else:
            if b == 'C':
                c_to_c += 1
            else:
                c_to_d += 1

    total_c = c_to_c + c_to_d

    retributive = (
        d_to_d > 0 and
        d_to_d * 2 >= d_to_c and
        (c_to_d == 0 or c_to_d * 3 <= c_to_c)
    )

    forgiving = (
        (d_to_c >= 2 and d_to_c > d_to_d) or
        (opp_d == 0 and d_to_c >= 1)
    )

    if last_opp == 'D':
        if last_me == 'D':
            if retributive and opp_c * 2 >= n:
                return 'C'
            if opp_c * 5 >= n * 3 and (total_c < 4 or c_to_d * 3 <= c_to_c):
                return 'C'
            if forgiving:
                return 'C'
            return 'D'

        if (
            retributive and
            opp_c * 2 >= n and
            ((n >= 2 and me[-2] == 'D') or r_my_d >= 2)
        ):
            return 'C'

        if n >= 2 and me[-2] == 'D':
            if opp_c * 5 >= n * 3 or forgiving:
                return 'C'
            return 'D'

        if opp_c * 10 >= n * 9 and r_opp_d <= 1 and c_to_d <= 1:
            return 'C'

        return 'D'

    if forgiving and not retributive:
        return 'D'

    if total_c >= 4 and c_to_d * 2 >= c_to_c:
        return 'D'

    if n >= 15 and opp_changes * 5 >= n * 4:
        return 'D'

    if opp_c * 10 < n * 3:
        return 'D'

    if opp_d * 10 >= n * 7 and r_opp_d >= 4:
        return 'D'

    return 'C'
